solution:
static int sumOf(int[] a) {
    int total = 0;
    for (int v : a) total += v;
    return total;
}

static void scaleInPlace(int[] a, int k) {
    for (int i = 0; i < a.length; i++) {
        a[i] = a[i] * k;
    }
}

static int[] withoutNegatives(int[] a) {
    int count = 0;
    for (int v : a) {
        if (v >= 0) count++;
    }
    int[] out = new int[count];
    int j = 0;
    for (int v : a) {
        if (v >= 0) {
            out[j] = v;
            j++;
        }
    }
    return out;
}
